object MaxPalette {
    /** Colour way names, in the order of [data]: each has a dark entry, then a light one. */
    @JvmField
    val WAYS = arrayOf("Feb23", "Gu", "Lebedev", "Mar8", "Moscow", "Nature", "Neon", "Simple", "Space", "Sphere")

    @JvmStatic
    fun table(way: Int, dark: Boolean): IntArray = data((way.coerceIn(0, WAYS.size - 1)) * 2 + (if (dark) 0 else 1))

    private val cache = arrayOfNulls<IntArray>(20)

    private fun data(i: Int): IntArray {
        cache[i]?.let { return it }
        val parsed = TABLES[i].split(',').map { it.toInt() }.toIntArray()
        cache[i] = parsed
        return parsed
    }

